#include <iostream>
#include <cmath>

int main() {
    int p, k;
    std::cin >> p >> k;
    const long long MOD = 1000000007;

    if (k == 0) {
        long long result = 1;
        long long base = p % MOD;
        long long exp = p - 1;
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        std::cout << res << std::endl;
    } else if (k == 1) {
        long long result = 1;
        long long base = p % MOD;
        long long exp = p;
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        std::cout << res << std::endl;
    } else {
        long long product_mod = 1;
        int i;
        for (i = 1; i <= p; ++i) {
            product_mod = (product_mod * k) % p;
            if (product_mod == 1) {
                break;
            }
        }
        long long exponent = (p - 1) / i;
        long long base = p % MOD;
        long long exp = exponent;
        long long res = 1;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        std::cout << res << std::endl;
    }
    return 0;
}
